// Requirements:
// - Clicking Add 5 Marks should update that student's marks.
// - Other students' marks must remain unchanged.
// - Don't directly mutate existing state objects.
// - Update React state correctly.
// - Preserve the existing functionality.


// ===========================================
//          Code After Solved Bugs
// ===========================================

import { useState } from "react";

function Task4() {
  const [students, setStudents] = useState([
    { id: 1, name: "Rahul", marks: 75 },
    { id: 2, name: "Priya", marks: 85 },
    { id: 3, name: "Arjun", marks: 60 }
  ]);

  function updateMarks(id, newMarks) {
    const updatedStudents = students.filter((student) => {
      if (student.id === id) {
        student.marks = newMarks;
      }
      return student;
    });
    setStudents(updatedStudents);
  }

  return (
    <div>
      <h2>Student Marks</h2>
      {students.map((student) => (
        <div key={student.id}>
          <p>{student.name}: {student.marks}</p>
          <button onClick={() => updateMarks(student.id, student.marks + 5)}>Add 5 Marks</button>
        </div>
      ))}
    </div>
  );
}

export default Task4;